async function submitDangerousDelete(){const mode=dangerousDeleteMode();const payload={token:dangerousDeleteToken,mode};if(mode==='cid'){payload.cid=Math.floor(Number(byId('dangerousDeleteCID')?.value||0));if(payload.cid<=0){toast(i18nFormat('result.failed',{action:i18nFormat('operation.delete'),error:i18nFormat('validation.positive_cid')}));return}}else if(mode==='uid'){payload.uid=Math.floor(Number(byId('dangerousDeleteUID')?.value||0));if(payload.uid<=0){toast(i18nFormat('result.failed',{action:i18nFormat('operation.delete'),error:i18nFormat('validation.positive_uid')}));return}}else{payload.uid_min=Math.floor(Number(byId('dangerousDeleteMinUID')?.value||0));payload.uid_max=Math.floor(Number(byId('dangerousDeleteMaxUID')?.value||0));if(payload.uid_min<=0||payload.uid_max<payload.uid_min){toast(i18nFormat('result.failed',{action:i18nFormat('operation.delete'),error:i18nFormat('validation.uid_range')}));return}}const token=payload.token;dangerousDeleteToken='';byId('modal').close();await guarded('Range purge',async()=>{payload.token=token;const x=await api('dangerousDeleteAsync',payload);const inner=x.result||{};if(!inner.ok)throw new Error(inner.error||i18nFormat('error.delete_failed'));setTimeout(refreshAll,1500);return inner})}
