async function submitAuto(forceStart){const shoutMin=Math.floor(Number(byId('autoShoutMin').value||0)),shoutMax=Math.floor(Number(byId('autoShoutMax').value||0));if(shoutMin<1||shoutMax<shoutMin||shoutMax>86400){toast(i18nFormat('result.failed',{action:i18nFormat('action.auto'),error:i18nFormat('validation.shout_interval')}));return}const enabled=forceStart===true||forceStart===null&&byId('autoEnabled').checked;const updates={'auto.auto_target_online_count':String(byId('autoTarget').value||20),'auto.auto_shout_interval_min_sec':String(shoutMin),'auto.auto_shout_interval_max_sec':String(shoutMax),'auto.auto_actions':String(enabled),'auto.auto_mail_notify':String(byId('autoMailNotify').checked),'spawn.spawn_fixed':String(byId('spawnFixed').checked),'spawn.spawn_village':String(byId('spawnVillage').value||3),'spawn.spawn_area':String(byId('spawnArea').value||0)};closeModal();await guarded('Auto',async()=>{const config=await api('robotConfigUpdate',{updates});const auto=await api(enabled?'autoStart':'autoStop');setTimeout(refreshAll,1000);return {config,auto}})}
async function submitGamePort(){const payload={game_port:Math.floor(Number(byId('gamePort').value||0)),monitor_port:Math.floor(Number(byId('monitorPort').value||0)),auction_port:Math.floor(Number(byId('auctionPort').value||0)),point_port:Math.floor(Number(byId('pointPort').value||0)),relay_port:Math.floor(Number(byId('relayPort').value||0)),game_host:byId('gameHost').value.trim(),login_ip:byId('loginIP').value.trim(),auction_host:byId('auctionHost').value.trim(),point_host:byId('pointHost').value.trim(),relay_host:byId('relayHost').value.trim(),service_root:byId('serviceRoot').value.trim(),run_script:byId('serviceRunScript').value.trim()};if([payload.game_port,payload.monitor_port,payload.auction_port,payload.point_port,payload.relay_port].some(p=>p<1||p>65535)){toast(i18nFormat('result.failed',{action:i18nFormat('operation.ports'),error:i18nFormat('validation.port_range')}));return}closeModal();if(busy)return;setBusy(true);try{const x=await fetch('/api/game-endpoint',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}).then(r=>r.json());writeLog(x);if(!x.ok)throw new Error(x.error||i18nFormat('error.save_ports_failed'));toast(x.message?i18nText(x.message):i18nFormat('message.saved_restart'));setTimeout(refreshAll,1000)}catch(e){writeLog({ok:false,error:e.message});toast(i18nFormat('result.failed',{action:i18nFormat('operation.ports'),error:e.message}))}finally{setBusy(false)}}
async function openPortsDialog(){await guarded('Ports',async()=>{const endpoint=await fetch('/api/game-endpoint').then(r=>r.json());if(!endpoint.ok)throw new Error(endpoint.error||i18nFormat('error.read_endpoint_failed'));const ports=endpoint.ports||{},hosts=endpoint.hosts||{};const body='<div class="formgrid"><label>Game Host</label><input id="gameHost" value="'+escapeHTML(endpoint.connect_setting||'auto')+'"><label>Login IP</label><input id="loginIP" value="'+escapeHTML(endpoint.inner_ip||'10.0.0.1')+'"><label>Game</label><input id="gamePort" type="number" min="1" max="65535" value="'+escapeHTML(ports.game||10011)+'"><label>Monitor</label><input id="monitorPort" type="number" min="1" max="65535" value="'+escapeHTML(ports.monitor||30303)+'"><label>Auction</label><input id="auctionPort" type="number" min="1" max="65535" value="'+escapeHTML(ports.auction||30803)+'"><label>Auction Host</label><input id="auctionHost" value="'+escapeHTML(hosts.auction||'127.0.0.1')+'"><label>Point</label><input id="pointPort" type="number" min="1" max="65535" value="'+escapeHTML(ports.point||30603)+'"><label>Point Host</label><input id="pointHost" value="'+escapeHTML(hosts.point||'127.0.0.1')+'"><label>Relay</label><input id="relayPort" type="number" min="1" max="65535" value="'+escapeHTML(ports.relay||7200)+'"><label>Relay Host</label><input id="relayHost" value="'+escapeHTML(hosts.relay||'127.0.0.1')+'"><label>Service Root</label><input id="serviceRoot" value="'+escapeHTML(endpoint.service_root||'/home/neople')+'"><label>Run Script</label><input id="serviceRunScript" value="'+escapeHTML(endpoint.run_script||'/root/run')+'"></div>';const foot='<button onclick="submitGamePort()">Save Ports</button><button class="danger" onclick="restartRobot()">Restart Robot</button>';showModal('Ports',body,foot)})}
async function openCompatDialog(){await guarded('Compat',async()=>{const x=await fetch('/api/compat').then(r=>r.json());if(!x.ok)throw new Error(x.error||i18nFormat('error.read_compat_failed'));const s=x.result||{};const msg=s.message?('<div class="muted" style="grid-column:1/-1">'+escapeHTML(i18nText(s.message))+'</div>'):'';const body='<div class="formgrid"><label>Guard</label><label><input id="mailboxBadNodeGuard" type="checkbox" '+(s.desired_enabled?'checked':'')+'> Mailbox cleanup</label><label>State</label><div>'+escapeHTML(i18nText(s.state||'-'))+'</div><label>Game</label><div>PID '+escapeHTML(s.pid||'-')+' / '+escapeHTML(s.port||'-')+'</div><div class="muted" style="grid-column:1/-1">DNF 70 only. Changes are applied to the running game process when available.</div>'+msg+'</div>';showModal('70 Compat',body,'<button onclick="closeModal()">Cancel</button><button class="primary" onclick="submitCompat()">Save</button>','compact')})}
