async function restartRobot(){if(busy)return;setBusy(true);try{const x=await fetch('/api/restart-robot',{method:'POST'}).then(r=>r.json());writeLog(x);if(!x.ok)throw new Error(x.error||i18nFormat('error.restart_failed'));toast(x.message?i18nText(x.message):i18nFormat('message.restart_queued'));setTimeout(()=>location.reload(),5000)}catch(e){writeLog({ok:false,error:e.message});toast(i18nFormat('result.failed',{action:i18nFormat('operation.restart'),error:e.message}));setBusy(false)}}
function keyStateText(r){if(r.key_state==='default'||r.using_default)return i18nFormat('key.project_default');if(r.key_state==='user')return i18nFormat('key.user');if(r.key_state==='invalid')return i18nFormat('key.invalid');if(r.key_state==='missing')return i18nFormat('key.missing');return r.key_state||'-'}
function keyCompleteText(r){return i18nFormat(r.game_valid?'common.complete':'common.incomplete')}
