async function openMaxDialog(){await guarded('Read max user',async()=>{const x=await fetch('/api/max-user').then(r=>r.json());if(!x.ok)throw new Error(x.error||i18nFormat('error.read_max_failed'));showModal('Max Online','<div class="formgrid"><label>Max online</label><input id="maxUserNum" type="number" min="1" max="1000000" value="'+escapeHTML(x.max_user_num||1000)+'"><label>Config files</label><div>'+escapeHTML(i18nFormat('max.files',{count:(x.files||[]).length}))+'</div><div class="muted" style="grid-column:1/-1">Updates max_user_num in all cfg files under the df_game_r cfg directory.</div></div>','<button onclick="closeModal()">Cancel</button><button class="primary" onclick="submitMaxUser()">Save</button>')})}
async function submitMaxUser(){const n=Math.floor(Number(byId('maxUserNum').value||0));if(!n||n<1){toast(i18nFormat('result.failed',{action:i18nFormat('operation.max'),error:i18nFormat('validation.positive_number')}));return}closeModal();if(busy)return;setBusy(true);try{const x=await fetch('/api/max-user',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({max_user_num:n})}).then(r=>r.json());if(!x.ok)throw new Error(x.error||i18nFormat('error.update_max_failed'));gameMaxUser=n;byId('mOnlineLabel').textContent=i18nFormat('dashboard.online_max',{max:n});writeLog(x);toast(x.message?i18nText(x.message):i18nFormat('max.files',{count:(x.files||[]).length}));setTimeout(refreshAll,1000)}catch(e){writeLog({ok:false,error:e.message});toast(i18nFormat('result.failed',{action:i18nFormat('operation.max'),error:e.message}))}finally{setBusy(false)}}
async function openScriptDialog(){try{const s=await fetch('/api/server-script').then(r=>r.json());const state=s.error?(i18nFormat('common.failed')+': '+s.error):(s.started_at?i18nFormat('script.submitted',{command:s.action||s.script||'',time:s.started_at}):i18nFormat('common.idle'));showModal('Server Scripts','<div class="formgrid"><label>Last command</label><div>'+escapeHTML(state)+'</div><label>/root/run</label><div>Start game services</div><label>/root/stop</label><div>Stop game services</div></div>','<button onclick="closeModal()">Cancel</button><button class="primary" onclick="submitServerScript(&quot;run&quot;)">Run /root/run</button><button class="danger" onclick="submitServerScript(&quot;stop&quot;)">Run /root/stop</button>')}catch(e){toast(i18nFormat('result.failed',{action:i18nFormat('operation.script_status'),error:e.message}))}}
async function submitServerScript(action){closeModal();const button=byId('scriptButton');if(button)button.disabled=true;try{const x=await fetch('/api/server-script',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action})}).then(r=>r.json());writeLog(x);if(!x.ok)throw new Error(x.error||i18nFormat('error.script_failed'));toast(i18nFormat('result.started',{action:x.script||action}));setTimeout(refreshAll,1000)}catch(e){writeLog({ok:false,error:e.message});toast(i18nFormat('result.failed',{action:i18nFormat('operation.script'),error:e.message}))}finally{if(button)button.disabled=false}}
async function openMarketDialog(){await guarded('Market',async()=>{const x=await api('marketStatus');showMarketDialog(resultOf(x)||{});return x})}
function marketSection(title,rows){return '<div class="formsection"><h4>'+escapeHTML(title)+'</h4><div class="formgrid">'+rows+'</div></div>'}
function marketNumber(id,value,min,max,step){return '<input id="'+id+'" type="number" min="'+min+'" max="'+max+'" step="'+(step||1)+'" value="'+escapeHTML(value)+'" onchange="autoSaveMarketConfig()">'}
function marketField(control,unit){return '<div class="market-field">'+control+(unit?'<span>'+escapeHTML(unit)+'</span>':'')+'</div>'}
function marketRange(left,right,unit){return '<div class="market-range">'+left+'<span>～</span>'+right+(unit?'<span>'+escapeHTML(unit)+'</span>':'')+'</div>'}
function marketPercent(value){return Math.round(Number(value||0)*10000)/100}
function showMarketDialog(s){
 const auto=s.auto||{},restock=s.restock||{},collector=s.collector||{},markets=auto.markets||['auction','cera'];
 const hasAuction=markets.includes('auction'),hasGold=markets.includes('cera')||markets.includes('gold'),allowedRarities=normalizeRarityDigits(restock.allowed_rarities??'01234');
 const cycleSec=Math.max(1,Math.round(Number(auto.interval_ms||60000)/1000)),initialSec=Math.max(0,Math.round(Number(auto.initial_delay_ms||0)/1000));
 let body=marketSection(i18nFormat('market.section_status'),'<label>'+escapeHTML(i18nFormat('common.status'))+'</label><div>'+escapeHTML(i18nFormat(s.auto_running?'common.running':'common.stopped'))+'</div><label>'+escapeHTML(i18nFormat('market.markets'))+'</label><div class="market-checks"><label><input id="marketAuction" type="checkbox" '+(hasAuction?'checked':'')+' onchange="autoSaveMarketConfig()"> '+escapeHTML(i18nFormat('market.auction'))+'</label><label><input id="marketGold" type="checkbox" '+(hasGold?'checked':'')+' onchange="autoSaveMarketConfig()"> '+escapeHTML(i18nFormat('market.gold'))+'</label></div>');
 body+=marketSection('Automatic Run','<label>Initial delay</label>'+marketField(marketNumber('marketInitialSeconds',initialSec,0,86400,1),'seconds')+'<label>Cycle</label>'+marketField(marketNumber('marketCycleSeconds',cycleSec,60,86400,1),'seconds')+'<label>Max actions</label>'+marketField(marketNumber('marketAutoMaxActions',auto.max_actions??10000,0,1000000,1))+'<label>Concurrent</label>'+marketField(marketNumber('marketAutoConcurrent',auto.max_concurrent??8,1,256,1))+'<label>Continue on error</label><label><input id="marketContinueOnError" type="checkbox" '+(auto.continue_on_error!==false?'checked':'')+' onchange="autoSaveMarketConfig()"> On</label>');
 body+=marketSection('Listing Filters','<label>Listed rarities (0-9)</label>'+marketField('<input id="marketAllowedRarities" inputmode="numeric" maxlength="10" pattern="[0-9]*" placeholder="01234" value="'+escapeHTML(allowedRarities)+'" data-prev="'+escapeHTML(allowedRarities)+'" oninput="sanitizeMarketAllowedRarities(this)" onchange="changeMarketAllowedRarities(this)">')+'<label>Equipment level</label>'+marketRange(marketNumber('marketEquipmentLevelMin',restock.equipment_level_min??0,0,999,1),marketNumber('marketEquipmentLevelMax',restock.equipment_level_max??0,0,999,1)));
 body+=marketSection('Equipment Generation','<label>Equipment quantity</label>'+marketRange(marketNumber('marketEquipmentQtyMin',restock.equipment_qty_min??2,1,10000,1),marketNumber('marketEquipmentQtyMax',restock.equipment_qty_max??5,1,10000,1))+'<label>Upgrade</label>'+marketRange(marketNumber('marketUpgradeMin',restock.upgrade_min??7,0,31,1),marketNumber('marketUpgradeMax',restock.upgrade_max??13,0,31,1))+'<label>Stack sizes</label>'+marketField('<input id="marketStackSizes" value="'+escapeHTML((restock.stack_sizes||[500,1000,2000]).join(','))+'" onchange="autoSaveMarketConfig()">'));
 body+=marketSection('Price Formula','<label>Equipment multiplier</label>'+marketRange(marketNumber('marketInflateMin',restock.equipment_inflate_min??5,1,1000,1),marketNumber('marketInflateMax',restock.equipment_inflate_max??8,1,1000,1))+'<label>Upgrade price / level</label>'+marketField(marketNumber('marketUpgradeRate',marketPercent(restock.upgrade_price_rate??0.08),0,1000,0.1),'%')+'<label>Final fluctuation</label>'+marketRange(marketNumber('marketRandLow',marketPercent(restock.rand_low??0.9),0.01,10000,0.1),marketNumber('marketRandHigh',marketPercent(restock.rand_high??1.1),0.01,10000,0.1),'%'));
 body+=marketSection('Restock Limits','<label>Max actions</label>'+marketField(marketNumber('marketRestockMaxActions',restock.max_actions??10000,0,1000000,1))+'<label>Concurrent</label>'+marketField(marketNumber('marketRestockConcurrent',restock.max_concurrent??8,1,256,1))+'<label>Action delay</label>'+marketField(marketNumber('marketRestockDelay',restock.per_item_delay_ms??0,0,60000,1),'ms'));
 body+=marketSection('Virtual Collector','<label>Enabled</label><label><input id="marketCollectorEnabled" type="checkbox" '+(collector.enabled!==false?'checked':'')+' onchange="autoSaveMarketConfig()"> On</label><label>Price range policy</label><label><input id="marketPriceRangeEnabled" type="checkbox" '+(collector.price_range_enabled?'checked':'')+' onchange="autoSaveMarketConfig()"> On</label><label>In-range probability</label>'+marketField(marketNumber('marketInRangeProbability',marketPercent(collector.in_range_probability??0.8),0,100,0.1),'%')+'<label>Out-of-range probability</label>'+marketField(marketNumber('marketOutRangeProbability',marketPercent(collector.out_of_range_probability??0.05),0,100,0.1),'%')+'<label>Max actions</label>'+marketField(marketNumber('marketCollectMaxActions',collector.max_actions??0,0,1000000,1))+'<label>Concurrent</label>'+marketField(marketNumber('marketCollectConcurrent',collector.max_concurrent??8,1,256,1)));
 const foot='<div class="market-actions"><button title="Start market auto loop" class="primary" onclick="submitMarketStart()">On</button><button title="Stop market auto loop" onclick="submitMarketStop()">Off</button><button title="Fill missing market listings" onclick="submitMarketRestock()">Restock</button><button title="Buy back player buyout listings" onclick="submitMarketCollect()">Collect</button><button class="danger" title="Delete robot market listings from database" onclick="submitMarketClearStock()">Clear Stock</button><button class="danger" title="Export PVF iteminfo.dat, delete robot listings, release dat, then restart auction and gold services" onclick="submitMarketItemInfo()">ItemInfo</button><button class="danger" title="Patch running auction memory for level and refine search limits" onclick="submitMarketMemoryPatch()">Memory Patch</button><button class="danger" title="Install a safe dp2 auction search hook while preserving socket data" onclick="submitMarketAuctionGuard()">Auction Guard</button></div>';
 showModal('Market',body,foot,'market')
}
function marketNumeric(id,fallback,min,max){let value=Number(byId(id)?.value);if(!Number.isFinite(value))value=fallback;if(min!==undefined)value=Math.max(min,value);if(max!==undefined)value=Math.min(max,value);return value}
function marketFormPayload(){
 const markets=[];if(byId('marketAuction').checked)markets.push('auction');if(byId('marketGold').checked)markets.push('cera');if(!markets.length){markets.push('auction');byId('marketAuction').checked=true}
 let levelMin=Math.floor(marketNumeric('marketEquipmentLevelMin',0,0,999)),levelMax=Math.floor(marketNumeric('marketEquipmentLevelMax',0,0,999));if(levelMax>0&&levelMax<levelMin)levelMax=levelMin;
 let qtyMin=Math.floor(marketNumeric('marketEquipmentQtyMin',2,1,10000)),qtyMax=Math.floor(marketNumeric('marketEquipmentQtyMax',5,1,10000));if(qtyMax<qtyMin)qtyMax=qtyMin;
 let inflateMin=Math.floor(marketNumeric('marketInflateMin',5,1,1000)),inflateMax=Math.floor(marketNumeric('marketInflateMax',8,1,1000));if(inflateMax<inflateMin)inflateMax=inflateMin;
 let upgradeMin=Math.floor(marketNumeric('marketUpgradeMin',7,0,31)),upgradeMax=Math.floor(marketNumeric('marketUpgradeMax',13,0,31));if(upgradeMax<upgradeMin)upgradeMax=upgradeMin;
 let randLow=marketNumeric('marketRandLow',90,0.01,10000)/100,randHigh=marketNumeric('marketRandHigh',110,0.01,10000)/100;if(randHigh<randLow)randHigh=randLow;
 const stackSizes=String(byId('marketStackSizes')?.value||'').split(',').map(x=>Math.floor(Number(x.trim()))).filter(x=>Number.isFinite(x)&&x>0);
 return {interval_ms:Math.floor(marketNumeric('marketCycleSeconds',60,60,86400)*1000),initial_delay_ms:Math.floor(marketNumeric('marketInitialSeconds',0,0,86400)*1000),auto_max_actions:Math.floor(marketNumeric('marketAutoMaxActions',10000,0,1000000)),auto_max_concurrent:Math.floor(marketNumeric('marketAutoConcurrent',8,1,256)),continue_on_error:!!byId('marketContinueOnError')?.checked,markets,allowed_rarities:normalizeRarityDigits(byId('marketAllowedRarities')?.value||''),equipment_level_min:levelMin,equipment_level_max:levelMax,equipment_qty_min:qtyMin,equipment_qty_max:qtyMax,stack_sizes:stackSizes.length?stackSizes:[500,1000,2000],equip_inflate_min:inflateMin,equip_inflate_max:inflateMax,upgrade_min:upgradeMin,upgrade_max:upgradeMax,upgrade_price_rate:marketNumeric('marketUpgradeRate',8,0,1000)/100,rand_low:randLow,rand_high:randHigh,restock_max_actions:Math.floor(marketNumeric('marketRestockMaxActions',10000,0,1000000)),restock_max_concurrent:Math.floor(marketNumeric('marketRestockConcurrent',8,1,256)),restock_per_item_delay_ms:Math.floor(marketNumeric('marketRestockDelay',0,0,60000)),collector_enabled:!!byId('marketCollectorEnabled')?.checked,price_range_enabled:!!byId('marketPriceRangeEnabled')?.checked,in_range_probability:marketNumeric('marketInRangeProbability',80,0,100)/100,out_of_range_probability:marketNumeric('marketOutRangeProbability',5,0,100)/100,collector_max_actions:Math.floor(marketNumeric('marketCollectMaxActions',0,0,1000000)),collector_max_concurrent:Math.floor(marketNumeric('marketCollectConcurrent',8,1,256))}
}
function normalizeRarityDigits(value){const seen=new Set();return String(value??'').replace(/[^0-9]/g,'').split('').sort().filter(d=>!seen.has(d)&&seen.add(d)).join('')}function sanitizeMarketAllowedRarities(el){el.value=normalizeRarityDigits(el.value)}
async function changeMarketAllowedRarities(el){sanitizeMarketAllowedRarities(el);const prev=el.dataset.prev||'';if(el.value===prev)return;if(!confirm(i18nFormat('market.rarity_confirm'))){el.value=prev;return}clearTimeout(marketConfigTimer);const payload=marketFormPayload(),c=Number(byId('marketRestockConcurrent')?.value||8);closeModal();await guarded('Market rarity filter',async()=>{await api('marketConfigUpdate',payload);const x=await api('marketRestockOnce',{market:'auction',max_concurrent:c,continue_on_error:true});setTimeout(refreshAll,1000);return x})}
let marketConfigTimer=null;function autoSaveMarketConfig(){clearTimeout(marketConfigTimer);marketConfigTimer=setTimeout(async()=>{try{await api('marketConfigUpdate',marketFormPayload());toast(i18nFormat('message.market_saved'))}catch(e){toast(i18nFormat('result.failed',{action:i18nFormat('operation.market_config'),error:e.message}))}},350)}
